CREATE TABLE IF NOT EXISTS mb_artist_top_recording ("artistId" VARCHAR(36), "recordingMbid" uuid, "listenCount" BIGINT NOT NULL, "userCount" BIGINT NOT NULL, CONSTRAINT pk_mb_artist_top_recording PRIMARY KEY ("artistId", "recordingMbid"), CONSTRAINT fk_mb_artist_top_recording_artistid__id FOREIGN KEY ("artistId") REFERENCES mb_artist(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS mb_artist_top_recording_fetch ("artistId" VARCHAR(36) PRIMARY KEY, "fetchedAt" BIGINT NOT NULL, CONSTRAINT fk_mb_artist_top_recording_fetch_artistid__id FOREIGN KEY ("artistId") REFERENCES mb_artist(id) ON DELETE CASCADE ON UPDATE RESTRICT);
